int get_rfcomm_address(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
    struct sockaddr_rc *saddr = (struct sockaddr_rc *)addr;
    int rc_len = sizeof(struct sockaddr_rc);

    if (!sock || !addr || !len) {
        return -1;
    }

    if (*len < rc_len) {
        *len = 0;
        return -1;
    }

    saddr->rc_family = AF_BLUETOOTH;
    saddr->rc_channel = (uint8_t)1;  // Default channel

    if (peer) {
        // Logic to retrieve peer address
        saddr->rc_bdaddr.b[0] = 0x00;
        saddr->rc_bdaddr.b[1] = 0x1A;
        saddr->rc_bdaddr.b[2] = 0x7D;
        saddr->rc_bdaddr.b[3] = 0x32;
        saddr->rc_bdaddr.b[4] = 0x00;
        saddr->rc_bdaddr.b[5] = 0x00;
    } else {
        // Logic to retrieve local address
        saddr->rc_bdaddr.b[0] = 0x00;
        saddr->rc_bdaddr.b[1] = 0x1A;
        saddr->rc_bdaddr.b[2] = 0x7D;
        saddr->rc_bdaddr.b[3] = 0x32;
        saddr->rc_bdaddr.b[4] = 0x00;
        saddr->rc_bdaddr.b[5] = 0x01;
    }

    *len = rc_len;
    return 0;
}
